package com.termux.app.workspace;
import android.app.Application;import android.view.View;import com.termux.shared.terminal.io.extrakeys.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class ExtraKeysEnterRowTest {
 @Test public void enterFollowsPageBlockAndRowsRemain()throws Exception{ExtraKeysInfo info=new ExtraKeysInfo("[['ESC','PGUP'],['TAB','PGDN']]","default",ExtraKeysConstants.CONTROL_CHARS_ALIASES);ExtraKeyButton[][] rows=info.getMatrix();assertEquals(2,rows.length);assertEquals("ENTER",rows[0][2].getKey());assertEquals("",rows[1][2].getKey());assertEquals("ESC",rows[0][0].getKey());assertEquals("TAB",rows[1][0].getKey());assertEquals("PGUP",rows[0][1].getKey());assertEquals("PGDN",rows[1][1].getKey());assertEquals(Integer.valueOf(android.view.KeyEvent.KEYCODE_ENTER),ExtraKeysConstants.PRIMARY_KEY_CODES_FOR_STRINGS.get(rows[0][2].getKey()));}
 @Test public void modifierUsesYellowAndRestoresNormalIncludingReload()throws Exception{ExtraKeysView keys=new ExtraKeysView(RuntimeEnvironment.application,null);WorkspaceExtraKeysStyle.apply(keys);ExtraKeysInfo info=new ExtraKeysInfo("[['CTRL']]","default",ExtraKeysConstants.CONTROL_CHARS_ALIASES);keys.reload(info);android.widget.Button ctrl=(android.widget.Button)keys.getChildAt(0);SpecialButtonState state=keys.getSpecialButtons().get(SpecialButton.CTRL);state.setIsActive(true);assertEquals(0xffffd54f,ctrl.getCurrentTextColor());state.setIsLocked(true);keys.reload(info);ctrl=(android.widget.Button)keys.getChildAt(0);assertEquals(0xffffd54f,ctrl.getCurrentTextColor());state.setIsLocked(false);state.setIsActive(false);assertEquals(WorkspaceDialogs.TEXT,ctrl.getCurrentTextColor());}
 @Test public void enterSpansTwoRowsAndToolbarHasOnlyKeys()throws Exception{ExtraKeysView keys=new ExtraKeysView(RuntimeEnvironment.application,null);keys.reload(new ExtraKeysInfo("[['ESC','PGUP'],['TAB','PGDN']]","default",ExtraKeysConstants.CONTROL_CHARS_ALIASES));assertEquals(5,keys.getChildCount());android.widget.Button enter=(android.widget.Button)keys.getChildAt(2);assertEquals("",enter.getText().toString());assertEquals("Enter",enter.getContentDescription());keys.measure(View.MeasureSpec.makeMeasureSpec(320,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(100,View.MeasureSpec.EXACTLY));keys.layout(0,0,320,100);assertEquals(keys.getChildAt(1).getTop(),enter.getTop());assertEquals(keys.getChildAt(4).getBottom(),enter.getBottom());assertTrue(enter.getLeft()>=keys.getChildAt(1).getRight());assertEquals(1,new com.termux.app.terminal.io.TerminalToolbarViewPager.PageAdapter(null,null).getCount());}
 @Test public void existingEnterAndLayoutsWithoutPageUpAreNotDuplicated()throws Exception{for(String json:new String[]{"[['ENTER','PGUP']]","[['ESC','TAB']]"})assertEquals(1,new ExtraKeysInfo(json,"default",ExtraKeysConstants.CONTROL_CHARS_ALIASES).getMatrix().length);}
}
